def has_close_elements(numbers: List[float], threshold: float) -> bool:
    """
    Return True if any two numbers in ``numbers`` are closer to each other than
    ``threshold``.  The distance between numbers is measured as the absolute
    difference.  Elements must be numeric (int or float).  ``threshold`` must be a
    non‑negative number.  The function raises a :class:`TypeError` if the input
    types are incorrect and a :class:`ValueError` if ``threshold`` is negative.
    """
    # Validate threshold
    try:
        threshold = float(threshold)
    except (TypeError, ValueError):
        raise TypeError("threshold must be a numeric value") from None

    if threshold < 0:
        raise ValueError("threshold must be non-negative")

    # Validate numbers and convert to a list
    try:
        elems = list(numbers)
    except TypeError:
        raise TypeError("numbers must be an iterable of numeric values") from None

    # Check all elements are numeric
    for i, val in enumerate(elems):
        if not isinstance(val, (int, float)):
            raise TypeError(f"Element at index {i} ({val!r}) is not numeric")

    # Trivial cases
    if len(elems) < 2:
        return False

    # Sort and compare adjacent pairs
    try:
        sorted_vals = sorted(elems)
    except TypeError as exc:
        raise TypeError("All elements in numbers must be comparable") from exc

    for a, b in zip(sorted_vals, sorted_vals[1:]):
        if abs(b - a) < threshold:
            return True
    return False

