def max_value_on_paths(N: int, grid_values: list) -> int:
    # Build the grid with 1-based indexing
    if N <= 0:
        return 0
    # Initialize grid with zeros
    grid = [[0] * (N + 1) for _ in range(N + 1)]
    for x, y, val in grid_values:
        if x == 0 and y == 0 and val == 0:
            break
        if 1 <= x <= N and 1 <= y <= N:
            grid[x][y] = val

    # DP arrays: previous and current step
    neg_inf = -10**15
    dp_prev = [[neg_inf] * (N + 1) for _ in range(N + 1)]
    # Initial position (1,1) at step t=2
    dp_prev[1][1] = grid[1][1]

    max_step = 2 * N
    for t in range(3, max_step + 1):
        dp_cur = [[neg_inf] * (N + 1) for _ in range(N + 1)]
        # x1 and x2 must be within [max(1, t-N), min(N, t-1)]
        min_x = max(1, t - N)
        max_x = min(N, t - 1)
        for x1 in range(min_x, max_x + 1):
            y1 = t - x1
            if y1 < 1 or y1 > N:
                continue
            for x2 in range(min_x, max_x + 1):
                y2 = t - x2
                if y2 < 1 or y2 > N:
                    continue
                best = neg_inf
                # previous positions for path 1: x1 or x1-1
                for px1 in (x1, x1 - 1):
                    if px1 < 1 or px1 > N:
                        continue
                    py1 = (t - 1) - px1
                    if py1 < 1 or py1 > N:
                        continue
                    for px2 in (x2, x2 - 1):
                        if px2 < 1 or px2 > N:
                            continue
                        py2 = (t - 1) - px2
                        if py2 < 1 or py2 > N:
                            continue
                        prev_val = dp_prev[px1][px2]
                        if prev_val == neg_inf:
                            continue
                        if x1 == x2 and y1 == y2:
                            val = prev_val + grid[x1][y1]
                        else:
                            val = prev_val + grid[x1][y1] + grid[x2][y2]
                        if val > best:
                            best = val
                dp_cur[x1][x2] = best
        dp_prev = dp_cur

    result = dp_prev[N][N]
    return result if result != neg_inf else 0

