def optimize_seating(M: int, N: int, K: int, L: int, D: int, chatting_pairs: list) -> (str, str):
    """
    Optimize the placement of aisles in a classroom to minimize the amount of chatting between students.

    Args:
    M (int): The number of rows in the classroom.
    N (int): The number of columns in the classroom.
    K (int): The number of horizontal aisles to add.
    L (int): The number of vertical aisles to add.
    D (int): The number of chatting pairs in the classroom.
    chatting_pairs (list of tuples): A list of tuples, each containing the positions (Xi, Yi) and (Pi, Qi) of a chatting pair.

    Returns:
    (str, str): Two space-separated strings representing the optimal row and column indices for the aisles.
    """
    import math
    from itertools import combinations

    # Validate inputs
    if M < 1 or N < 1:
        return ("", "")
    if K < 0:
        K = 0
    if L < 0:
        L = 0
    max_row_aisles = max(0, M - 1)
    max_col_aisles = max(0, N - 1)
    if K > max_row_aisles:
        K = max_row_aisles
    if L > max_col_aisles:
        L = max_col_aisles

    # Preprocess pairs into (r1,c1,r2,c2)
    pairs = []
    for item in chatting_pairs:
        if len(item) != 4:
            continue
        r1, c1, r2, c2 = item
        # Validate coordinates
        if not (1 <= r1 <= M and 1 <= r2 <= M and 1 <= c1 <= N and 1 <= c2 <= N):
            continue
        pairs.append((r1, c1, r2, c2))

    # Precompute for each pair the set of horizontal and vertical aisle positions that would separate them
    horiz_sets = []  # list of set of aisles positions (1..M-1)
    vert_sets = []   # list of set of aisle positions (1..N-1)
    for r1, c1, r2, c2 in pairs:
        if r1 == r2:
            horiz_sets.append(set())
        else:
            a_low = min(r1, r2)
            a_high = max(r1, r2)
            horiz_sets.append(set(range(a_low, a_high)))  # aisles between a_low and a_high-1
        if c1 == c2:
            vert_sets.append(set())
        else:
            b_low = min(c1, c2)
            b_high = max(c1, c2)
            vert_sets.append(set(range(b_low, b_high)))

    # Define helper to count separated pairs for given aisle sets
    def count_separated(row_set, col_set):
        cnt = 0
        for hs, vs in zip(horiz_sets, vert_sets):
            if hs and row_set & hs:
                cnt += 1
            elif vs and col_set & vs:
                cnt += 1
        return cnt

    # If no aisles to add, return empty strings
    if K == 0 and L == 0:
        return ("", "")

    # Calculate number of combinations and decide strategy
    row_combinations = math.comb(max_row_aisles, K) if K > 0 else 1
    col_combinations = math.comb(max_col_aisles, L) if L > 0 else 1
    total_iters = row_combinations * col_combinations

    # Use brute-force if it is not too large, else fallback to greedy
    BRUTE_LIMIT = 200000  # adjust as needed
    best_rows = ()
    best_cols = ()
    best_count = -1

    # Prepare all possible combos
    row_options = list(range(1, max_row_aisles + 1))
    col_options = list(range(1, max_col_aisles + 1))

    if total_iters <= BRUTE_LIMIT:
        # Brute force
        if K == 0:
            row_combos = [()]
        else:
            row_combos = combinations(row_options, K)
        if L == 0:
            col_combos = [()]
        else:
            col_combos = combinations(col_options, L)
        for r_combo in row_combos:
            row_set = set(r_combo)
            for c_combo in col_combos:
                col_set = set(c_combo)
                cnt = count_separated(row_set, col_set)
                if cnt > best_count:
                    best_count = cnt
                    best_rows = r_combo
                    best_cols = c_combo
    else:
        # Greedy approach: select aisles that maximize incremental gain
        # Compute benefit of each horizontal aisle independently
        horiz_benefit = {}
        for a in row_options:
            cnt = 0
            for hs, vs in zip(horiz_sets, vert_sets):
                if a in hs:
                    cnt += 1
            horiz_benefit[a] = cnt
        # Sort by benefit descending, then by position ascending
        sorted_row = sorted(row_options, key=lambda x: (-horiz_benefit[x], x))
        best_rows = tuple(sorted_row[:K]) if K > 0 else ()
        # Similarly for vertical
        vert_benefit = {}
        for b in col_options:
            cnt = 0
            for hs, vs in zip(horiz_sets, vert_sets):
                if b in vs:
                    cnt += 1
            vert_benefit[b] = cnt
        sorted_col = sorted(col_options, key=lambda x: (-vert_benefit[x], x))
        best_cols = tuple(sorted_col[:L]) if L > 0 else ()

        # The greedy counts may overcount duplicates; adjust by evaluating separated pairs
        best_rows_set = set(best_rows)
        best_cols_set = set(best_cols)
        best_count = count_separated(best_rows_set, best_cols_set)

    # Format output strings
    row_str = " ".join(str(x) for x in best_rows) if best_rows else ""
    col_str = " ".join(str(x) for x in best_cols) if best_cols else ""
    return (row_str, col_str)

def polynomial_to_string(n: int, coeffs: List[int]) -> str:
    """
    Converts a list of polynomial coefficients into a formatted string representation.

    Args:
        n (int): The highest degree of the polynomial.
        coeffs (List[int]): A list of coefficients, starting with the coefficient of the highest degree term.

    Returns:
        str: The string representation of the polynomial.
    """
    # Ensure we have enough coefficients; pad with zeros if necessary
    if len(coeffs) < n + 1:
        coeffs = [0] * (n + 1 - len(coeffs)) + coeffs
    elif len(coeffs) > n + 1:
        # If too many, consider only the last n+1 coefficients (most significant first)
        coeffs = coeffs[-(n + 1):]

    parts = []
    first_term = True

    for i, coeff in enumerate(coeffs):
        degree = n - i
        if coeff == 0:
            continue

        # Determine sign
        if first_term:
            sign = '' if coeff > 0 else '-'
        else:
            sign = '+' if coeff > 0 else '-'

        abs_coeff = abs(coeff)

        # Determine coefficient string
        if abs_coeff == 1 and degree != 0:
            coeff_str = ''
        else:
            coeff_str = str(abs_coeff)

        # Determine variable part
        if degree == 0:
            var_part = ''
        elif degree == 1:
            var_part = 'x'
        else:
            var_part = f'x^{degree}'

        part = f"{sign}{coeff_str}{var_part}"
        parts.append(part)

        first_term = False

    if not parts:
        return '0'
    return ''.join(parts)

