def select_volunteers(n: int, m: int, applicants: list) -> tuple:
    """
    Selects and determines the interview score cutoff and the list of applicants who qualify for the interview process.

    The function sorts the applicants based on their test scores in descending order. If multiple applicants have the same score,
    they are then sorted by their registration number in ascending order. The interview score cutoff is calculated based on
    150% of the planned number of recruits, rounded down. All applicants with scores equal to or higher than the cutoff are
    considered qualified for the interview.

    Args:
        n (int): The total number of applicants.
        m (int): The planned number of volunteers to be recruited.
        applicants (list[tuple[int, int]]): A list of tuples where each tuple contains the registration number and test score
                                            of an applicant.

    Returns:
        tuple[int, list[tuple[int, int]]]: A tuple containing the interview score cutoff and a list of tuples, each of which
                                            includes the registration number and test score of qualified applicants.
    """
    # Basic validation
    try:
        if not isinstance(n, int) or not isinstance(m, int):
            raise TypeError("Parameters n and m must be integers.")
        if n < 0 or m < 0:
            raise ValueError("Parameters n and m must be non-negative.")
        if not isinstance(applicants, list):
            raise TypeError("Applicants must be a list.")
        if len(applicants) != n:
            raise ValueError("Length of applicants list does not match n.")
        for item in applicants:
            if not isinstance(item, tuple) or len(item) != 2:
                raise TypeError("Each applicant must be a tuple of (registration, score).")
            reg, score = item
            if not isinstance(reg, int) or not isinstance(score, int):
                raise TypeError("Registration and score must be integers.")
    except Exception as e:
        raise ValueError(f"Invalid input: {e}") from None

    if n == 0 or m == 0:
        return (0, [])

    # Sort applicants: score descending, registration ascending for ties
    sorted_applicants = sorted(applicants, key=lambda x: (-x[1], x[0]))

    # Determine cutoff position (1-based rank)
    import math
    cutoff_pos = math.floor(1.5 * m)

    if cutoff_pos <= 0:
        # No cutoff defined
        return (0, [])
    if cutoff_pos > n:
        cutoff_pos = n

    # Get cutoff score from the applicant at cutoff_pos-1
    cutoff_score = sorted_applicants[cutoff_pos - 1][1]

    # Filter qualified applicants
    qualified = [app for app in sorted_applicants if app[1] >= cutoff_score]

    return (cutoff_score, qualified)

