                valid_herbs.append(herb)

    if not valid_herbs:
        return 0

    # 1D DP for 0/1 knapsack
    dp = [0] * (T + 1)
    for time_cost, value in valid_herbs:
        for cap in range(T, time_cost - 1, -1):
            new_val = dp[cap - time_cost] + value
            if new_val > dp[cap]:
                dp[cap] = new_val

    return dp[T] if dp else 0

